<script setup>
import { computed, onMounted, ref } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { supabase } from '../services/supabase'
import { getMyProfile, signOut } from '../services/account'
const props=defineProps({title:{type:String,default:'Overview'},subtitle:{type:String,default:''}})
const route=useRoute(),router=useRouter(),profile=ref(null),menuOpen=ref(false),unread=ref(0)
const isEmployer=computed(()=>['employer','admin'].includes(profile.value?.account_type)||profile.value?.role==='admin')
const isAdmin=computed(()=>profile.value?.role==='admin')
const theme=ref(localStorage.getItem('campusgig-theme')||'light')
function applyTheme(){document.documentElement.dataset.theme=theme.value;localStorage.setItem('campusgig-theme',theme.value)}
function toggleTheme(){theme.value=theme.value==='light'?'dark':'light';applyTheme()}
async function load(){const x=await getMyProfile({force:true});profile.value=x.profile;const {count}=await supabase.from('notifications').select('*',{count:'exact',head:true}).eq('user_id',x.user?.id).eq('is_read',false);unread.value=count||0}
async function logout(){await signOut();router.push('/')}
onMounted(()=>{applyTheme();load()})
const nav=computed(()=>[{label:'Overview',to:'/dashboard',icon:'⌂'},{label:'Find jobs',to:'/jobs',icon:'⌕'},{label:'Saved jobs',to:'/saved',icon:'♡'},...(isEmployer.value?[{label:'Post a job',to:'/post-job',icon:'＋'},{label:'My job posts',to:'/my-jobs',icon:'▤'},{label:'Applicants',to:'/applicants',icon:'♧'}]:[{label:'My applications',to:'/applications',icon:'▣'}]),{label:'Notifications',to:'/notifications',icon:'◉'},{label:'Community',to:'/community',icon:'✳'},{label:'My profile',to:'/profile',icon:'◌'},{label:'Settings',to:'/settings',icon:'⚙'},...(isAdmin.value?[{label:'Admin centre',to:'/admin',icon:'♜'}]:[])])
</script>
<template><div class="app-layout"><aside class="sidebar" :class="{'sidebar-open':menuOpen}"><RouterLink to="/dashboard" class="brand-row"><span class="brand-mark">C</span><span><b>Campus Gig</b><small>Work. Learn. Grow.</small></span></RouterLink><div class="side-label">WORKSPACE</div><nav><RouterLink v-for="item in nav" :key="item.to" :to="item.to" class="nav-link" :class="{active:route.path===item.to}" @click="menuOpen=false"><span class="nav-icon">{{item.icon}}</span>{{item.label}}<i v-if="item.to==='/notifications'&&unread">{{unread}}</i></RouterLink></nav><div class="sidebar-bottom"><div class="mini-profile"><div class="avatar">{{(profile?.full_name||'U').slice(0,1).toUpperCase()}}</div><div><b>{{profile?.full_name||'Your account'}}</b><small>{{profile?.account_type||'Member'}}</small></div></div><button class="nav-link logout" @click="logout"><span class="nav-icon">↪</span>Log out</button></div></aside><div v-if="menuOpen" class="mobile-scrim" @click="menuOpen=false"></div><main class="main-area"><header class="topbar"><button class="mobile-menu" @click="menuOpen=!menuOpen">☰</button><div><b>{{title}}</b><small>{{subtitle}}</small></div><div class="top-actions"><button class="theme-toggle" @click="toggleTheme">{{theme==='light'?'☾ Dark mode':'☀ Light mode'}}</button><RouterLink to="/notifications" class="icon-action" aria-label="Notifications">♧<span v-if="unread"></span></RouterLink><RouterLink to="/profile" class="avatar">{{(profile?.full_name||'U').slice(0,1).toUpperCase()}}</RouterLink></div></header><section class="page-content"><slot :profile="profile" /></section></main></div></template>
<style scoped>
.app-layout{min-height:100vh;background:var(--bg)}.sidebar{position:fixed;inset:0 auto 0 0;width:248px;background:var(--navy);color:white;padding:25px 16px;display:flex;flex-direction:column;z-index:20}.brand-row{display:flex;align-items:center;gap:11px;padding:0 9px 30px}.brand-row b{display:block;font:800 17px 'Plus Jakarta Sans'}.brand-row small{display:block;color:#c4d4e0;font-size:10px;margin-top:2px}.side-label{padding:0 12px 12px;color:#9eb5c7;font-size:10px;letter-spacing:.13em;font-weight:800}.sidebar nav{display:grid;gap:5px}.nav-link{display:flex;align-items:center;gap:12px;padding:11px 12px;border-radius:10px;color:#d5e2ec;font-size:13px;font-weight:600}.nav-link:hover,.nav-link.active{background:#ffffff1b;color:white}.nav-link.active{box-shadow:inset 3px 0 var(--gold)}.nav-icon{width:20px;text-align:center;font-size:18px}.nav-link i{font-style:normal;margin-left:auto;background:var(--gold);color:var(--navy);font-size:10px;padding:2px 6px;border-radius:20px}.sidebar-bottom{margin-top:auto}.mini-profile{display:flex;gap:10px;align-items:center;padding:14px 8px;border-top:1px solid #ffffff25}.mini-profile b{display:block;font-size:12px}.mini-profile small{color:#b9cbd8;font-size:10px;text-transform:capitalize}.avatar{width:34px;height:34px;border-radius:50%;background:#dcecf5;color:var(--navy);display:grid;place-items:center;font-weight:800}.logout{width:100%;background:transparent;border:0;text-align:left}.main-area{margin-left:248px;min-height:100vh}.topbar{height:76px;position:sticky;top:0;z-index:10;background:var(--surface);border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;padding:0 34px}.topbar b{display:block;font:700 14px 'Plus Jakarta Sans'}.topbar small{display:block;color:var(--muted);font-size:11px;margin-top:3px}.top-actions{display:flex;align-items:center;gap:13px}.icon-action{position:relative;font-size:20px}.icon-action span{position:absolute;width:7px;height:7px;background:#ef4444;border-radius:50%;top:0;right:-3px}.page-content{max-width:1420px;margin:auto;padding:30px 34px 60px}.mobile-menu{display:none;background:none;border:0;color:var(--text);font-size:22px}.mobile-scrim{display:none}
@media(max-width:850px){.sidebar{transform:translateX(-100%);transition:.2s}.sidebar-open{transform:translateX(0)}.main-area{margin-left:0}.mobile-menu{display:block}.topbar{padding:0 17px;gap:12px}.topbar>div:first-of-type{margin-right:auto}.page-content{padding:22px 16px 45px}.theme-toggle{font-size:11px;padding:8px}.mobile-scrim{display:block;position:fixed;inset:0;background:#0008;z-index:19}}
</style>
